css:
body {
  font-size: 12px;
}

.button {
  width: 100px;
  color: #ff00ff
}

.next-table-fixed table {
  table-layout: fixed;
  background: transparent;
}

td.next-table-cell {
  background-color: transparent !important;
  text-align: center;
}

::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

/* 滚动条轨道 */
::-webkit-scrollbar-track {
  /*  background: rgb(239, 239, 239); */
  border-radius: 5px;
}

/*  小滑块 */
::-webkit-scrollbar-thumb {
  background: #40a0ff49;
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: #40a0ff;
}

.table-common {
  width: 100%;
}

.table-common tbody .next-table-cell-wrapper {
  width: 100px;
  /* 限制容器宽度 */
  white-space: nowrap;
  /* 禁止文本换行 */
  overflow: hidden;
  /* 隐藏超出范围的内容 */
  text-overflow: ellipsis;
  /* 使用省略号 */
}

.table-common .next-table-row td:nth-child(2) .next-table-cell-wrapper {
  width: 220px;
}

.table-common table {
  background: none;
}

.table-common .next-table-header {
  height: 32px;
}

.table-common .next-table-cell-wrapper {
  font-size: 16px !important;
  height: 32px !important;
  padding: 0 !important;
  line-height: 32px !important;
  text-align: center;
}

.table-common th {
  background: rgba(41, 121, 255, 0.3);
  color: #00CFE4;
}

.table-common .next-table-row {
  background: none;
  height: 29px;
  font-size: 14px;
}


.table-common.zebra tr:nth-child(even) td {
  background: rgba(26, 52, 93, 0.6);
}

/* .table-common .next-table-row.hovered {
  background: none !important;
}

.table-common .next-table-row.hovered td {
  background: none !important;
} */

.table-common td {
  color: rgba(255, 255, 255, 1);
  background-color: rgba(26, 52, 93, 1);
}

.table-common.zebra tr:nth-child(odd) td {
  background: none;
  /* opacity: 0.5; */
}

.table-common .next-table-body tr:nth-child(odd).hovered td {
  background: none;
  color: rgba(255, 255, 255, 1);
  /* opacity: 0.5; */
}

.table-common .next-table-body tr:nth-child(even).hovered td {

  color: rgba(255, 255, 255, 1);
  background: rgba(26, 52, 93, 0.6);
  /* color: #00CFE4; */
  /* opacity: 0.5; */
}

.bottom-btn-box {
  position: absolute;
  bottom: 20px;
  right: 410px;
  display: flex;
  flex-direction: column;
  width: 150px;
}

.bottom-btn {
  width: 132px;
  height: 46px !important;
  text-align: center;
  z-index: 100;
  cursor: pointer;
}

.btn-background-click {
  background: url('/simu/static/screenImg/mxxz-btn-click1.png') !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-size: 100% 100% !important;
}

.btn-background-unclick {
  background: url('/simu/static/screenImg/mxxz-btn-unclick1.png') !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-size: 100% 100% !important;
}

